head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil71611";
scwin.prgIfm = null;
scwin.upd_digitalAttachExcelfile = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.prgIfm = $c.util.getComponent('prgIfm');
        scwin.upd_digitalAttachExcelfile = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_digitalAttachExcelfile') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_digitalAttachExcelfile"]');
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil71611.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_DigitalExcelUpload_onclick
 * @description 「확인」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_DigitalExcelUpload_onclick = async function(e){
    try {
        await scwin.digitalExcelUpload()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil71611.btn_DigitalExcelUpload_onclick' }); }
};

/**
 * @method
 * @name btn_window_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil71611.btn_window_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_DigitalExcelUpload
 * @description Digital Excel Upload 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_DigitalExcelUpload = async function () {
    const sbmOptions = {
        id: "tx_fn_DigitalExcelUpload",
        method: "post",
        action: "/digital/DigitalList.do",
        ref: "dma_DigitalExcelUploadReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name digitalExcelUpload
 * @description digital Excel Upload 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.digitalExcelUpload = async function () {
    const form = (document.digitallistPageForm || { elements: [] });
    if (($c.util.getComponent('upd_digitalAttachExcelfile').getValue() === null ? '' : String($c.util.getComponent('upd_digitalAttachExcelfile').getValue())) === '') {
        await $c.win.alert("파일을 업로드해주세요.");
        return;
    } else {
        if (!scwin.checkFileType($c.util.getComponent('upd_digitalAttachExcelfile').getValue())) {
            await $c.win.alert("엑셀파일만 업로드 해주세요.");
            return;
        }
    }
    if (await $c.win.confirm("업로드 하시겠습니까?")) {
        ($c.util.getComponent("searchFile") && $c.util.getComponent("searchFile").hide ? $c.util.getComponent("searchFile").hide() : console.warn('[sdd] hide 대상 미해결: ' + "searchFile"));
        ($c.util.getComponent("confirmBtn") && $c.util.getComponent("confirmBtn").hide ? $c.util.getComponent("confirmBtn").hide() : console.warn('[sdd] hide 대상 미해결: ' + "confirmBtn"));
        scwin.prgIfm.setStyle("display", "");
        const previewWin = (Promise.resolve($c.win.openPopup("/progress_blank_pop/progress_blank_pop.xml", { id: "progressFrm", scrollbars: true, resizable: true, width: "300", height: "50", type: "pageFramePopup" }, {})).then(function () {}), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("progressFrm"); this.closed = true; } });
        form.action = "/digital/DigitalList.do";
        $c.util.getComponent('dma_DigitalExcelUploadReq').set('method', 'digitalExcelUpload');
        await scwin.tx_fn_DigitalExcelUpload();
    }
};

/**
 * @method
 * @name checkFileType
 * @description check File Type 처리
 * @param {*} filePath filePath
 * @returns {void}
 * @hidden N
 */
scwin.checkFileType = function (filePath) {
    const fileFormat = filePath.toLowerCase();
    if (fileFormat.indexOf(".xls") > -1) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name close_pop
 * @description close pop 처리
 * @returns {void}
 * @hidden N
 */
scwin.close_pop = function () {
    $c.win.setPageFrameSrc(null, '/jldfil71501/jldfil71501.xml', { method: "searchList", listBzCd: "1" });
    $c.win.closePopup();
};
